const data = $input.item.json;
const query = $('Research webhook').item.json.body.query || '';
const queryId = $('Research webhook').item.json.body.query_id || '';

// Extract useful content from DuckDuckGo response
const abstract = data.Abstract || '';
const abstractSource = data.AbstractSource || '';
const abstractURL = data.AbstractURL || '';
const definition = data.Definition || '';
const definitionSource = data.DefinitionSource || '';
const answer = data.Answer || '';

// Related topics
const topics = (data.RelatedTopics || []).slice(0, 5).map(t => {
  if (t.Text) return t.Text;
  if (t.Topics) return t.Topics.slice(0, 2).map(st => st.Text || '').join(' | ');
  return '';
}).filter(Boolean);

// Build content block
const parts = [];
if (answer) parts.push(`Quick Answer: ${answer}`);
if (abstract) parts.push(`Overview (${abstractSource}): ${abstract}`);
if (definition) parts.push(`Definition (${definitionSource}): ${definition}`);
if (topics.length) parts.push(`Related: ${topics.join(' • ')}`);

const content = parts.join('\n\n') || `No direct results found for: ${query}`;
const sources = [];
if (abstractURL) sources.push(abstractURL);
if (data.DefinitionURL) sources.push(data.DefinitionURL);

return [{ json: { query_id: queryId, content, sources } }];
